-- Heroic and Mythic boss loot, second pass (#7513: the Ring of Law bosses dropped no Mythic items).
-- rev_20261009_70 missed every AtlasLoot section whose name is not a plain BabbleBoss[...]: Ring of Law, the
-- Scarlet Monastery bosses (coloured names), Armory (Herod) and the Sunken Temple troll minibosses, and it did not
-- read Upper Blackrock Spire, so those Heroic/Mythic templates kept their Normal loot (or none) and the boss before
-- each section got its items too (High Interrogator Gerstahn carried the Ring of Law pool). Each listed template
-- now drops one item of its own Heroic (item level 61) or Mythic (64) pool per kill: AtlasLoot (Ascension Edition)
-- plus the gear the db.exil.es archive saw on that template at 3% or more (Ascension's relics, the Ragefire Chasm
-- rewards and the bosses AtlasLoot has no section for). Generated by dungeon-recherche/loot_atlas_bauen.py.
