-- One Mark of Triumph for every player in the instance when one of these bosses dies on Heroic or Mythic
-- (CoADungeonSpoils.cpp); finishing the dungeon still gives one more. Every dungeon boss except those that are
-- never killed or that the archive saw without a Mark: the Ironbarks, Aurius, Dathrohan (Balnazzar gives it),
-- Nefarius, the Scarshield Infiltrator, the courier, Pusillin, Sneed (his Shredder gives it), Sergeant Bly, Verek,
-- the Sunken Temple troll minibosses and Spawn of Hakkar, and six of the Seven, whose Mark comes with Doom'rel.
CREATE TABLE IF NOT EXISTS `coa_dungeon_mark_bosses` (
  `entry` int unsigned NOT NULL,
  PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM `coa_dungeon_mark_bosses`;
INSERT INTO `coa_dungeon_mark_bosses` (`entry`) SELECT `entry` FROM `coa_dungeon_bosses` WHERE `entry` NOT IN (643, 5708, 5711, 5712, 5716, 5717, 7604, 9034, 9035, 9036, 9037, 9038, 9040, 9042, 10162, 10299, 10812, 10917, 11082, 11491, 14241, 14354);

